// Nesneleri Sayıyorum — sunuma göre 10 etkinlik. Yalnızca Scripts Reload gerekir.
const ASSETS={"btn_ana": "data:image/png;base64,", "btn_ses_ackapa": "data:image/png;base64,", "btn_ses_ackapa_muted": "data:image/png;base64,", "cicek": "data:image/png;base64,", "say25": "data:image/png;base64,", "say36": "data:image/png;base64,", "say49": "data:image/png;base64,", "say74": "data:image/png;base64,", "say87": "data:image/png;base64,", "s_17": "data:image/png;base64,", "s_20": "data:image/png;base64,", "s_21": "data:image/png;base64,", "s_34": "data:image/png;base64,", "s_35": "data:image/png;base64,", "s_36": "data:image/png;base64,", "s_56": "data:image/png;base64,", "s_57": "data:image/png;base64,", "s_58": "data:image/png;base64,", "s_65": "data:image/png;base64,", "s_70": "data:image/png;base64,", "s_75": "data:image/png;base64,", "s_99": "data:image/png;base64,", "top": "data:image/png;base64,", "dogrucevap": "data:audio/webm;base64,", "fon": "data:audio/webm;base64,", "yanliscevap": "data:audio/webm;base64,", "btn_basla": "data:image/png;base64,", "yildiz": "data:image/png;base64,"};
const LEVELS = {
 1:{kind:'match',answer:[35],tiles:[34,35,36],slots:[[978,782,230,140]],positions:[[628,941],[982,941],[1316,941]],question:'Simitleri sayalım. Uygun sayıyı kutucuğa sürükleyelim.'},
 2:{kind:'match',answer:[57],tiles:[58,57,56],slots:[[943,731,230,140]],positions:[[628,915],[936,915],[1240,915]],question:'Düğmeleri sayalım. Uygun sayıyı kutucuğa sürükleyelim.'},
 3:{kind:'collect',answer:[25],source:'cicek',area:[390,300,1230,450],question:'Alana 25 tane çiçek sürükleyelim.'},
 4:{kind:'collect',answer:[42],initial:30,source:'top',area:[350,330,1250,420],question:'Alanda 30 top var. 42 top olması için uygun sayıda top ekleyelim.'},
 5:{kind:'match',answer:[21,17],tiles:[21,20,17],slots:[[1467,476,145,135],[1467,634,145,135]],positions:[[1139,820],[1346,820],[1548,820]],question:'Mor topları ve yıldızları sayalım. Sayıları uygun kutulara sürükleyelim.'},
 6:{kind:'choose',answer:[1],question:'Blokları sayalım. 38 olan grubun kutusunu işaretleyelim.'},
 7:{kind:'choose',answer:[1],question:'Blokları sayalım. 62 olan grubun kutusunu işaretleyelim.'},
 8:{kind:'match',answer:[75],tiles:[65,70,75],slots:[[812,894,245,160]],positions:[[1588,432],[1588,625],[1588,805]],question:'Boncukları sayalım. Uygun sayıyı kutucuğa sürükleyelim.'},
 9:{kind:'match',answer:[25,36,49],tiles:[49,25,36],words:true,slots:[[560,756,205,135],[980,756,205,135],[1401,756,205,135]],positions:[[342,902],[768,902],[1195,902]],question:'Sayıların yazılışlarını uygun kutulara sürükleyelim.'},
 10:{kind:'match',answer:[99,87,74],tiles:[87,74,99],words:true,slots:[[543,712,244,170],[1023,712,244,170],[1480,712,244,170]],positions:[[342,896],[766,900],[1191,902]],question:'Sayıların yazılışlarını uygun kutulara sürükleyelim.'}
};
const WORDS={25:'yirmi beş',36:'otuz altı',49:'kırk dokuz',74:'yetmiş dört',87:'seksen yedi',99:'doksan dokuz'};
function createCountingGame(runtime){
 const old=document.getElementById('nesne-ui');if(old)old.remove();
 const root=document.createElement('div');root.id='nesne-ui';root.setAttribute('lang','tr');document.body.append(root);
 const css=document.createElement('style');css.textContent=`
 #nesne-ui{position:fixed;width:1920px;height:1080px;transform-origin:0 0;pointer-events:none;z-index:9999;font-family:Arial,sans-serif;color:#173964;user-select:none}
 #nesne-ui *{box-sizing:border-box}#nesne-ui button{pointer-events:auto;cursor:pointer;font:700 29px Arial;color:#173964;border:3px solid #697ad9;border-radius:22px;background:#fffde8;padding:14px 22px;box-shadow:0 5px 0 #697ad9;touch-action:none}
 #nesne-ui button:hover{filter:brightness(1.06)}#nesne-ui button:focus-visible{outline:7px solid #ffb300}#nesne-ui button:active{transform:translateY(3px)}
 #nesne-ui button.hit{background:transparent;border:0;box-shadow:none;padding:0;border-radius:30px}#nesne-ui button.hit:hover{background:#ffffff22}
 #nesne-ui .tile{pointer-events:auto;cursor:grab;border:0;box-shadow:none;padding:0;background:transparent;position:absolute;touch-action:none;display:flex;align-items:center;justify-content:center;font-size:36px}
 #nesne-ui .word{font-size:30px}
 #nesne-ui .tile img{width:100%;height:100%;object-fit:contain;pointer-events:none}#nesne-ui .tile:hover{filter:brightness(1.06)}
 #nesne-ui button.slot{position:absolute;pointer-events:auto;border:0;box-shadow:none;background:transparent;padding:0;cursor:pointer}
 #nesne-ui .mark{border:7px solid;position:absolute;border-radius:20px;pointer-events:none;z-index:80;display:flex;justify-content:flex-end;font:bold 55px Arial}
 #nesne-ui .notice{position:absolute;left:430px;top:960px;width:1050px;text-align:center;background:#fffef0ee;border-radius:22px;padding:16px;font-size:29px;z-index:100}
 #nesne-ui .panel{pointer-events:auto;position:absolute;background:#fffdea;border:6px solid #8875d8;border-radius:35px;padding:45px;box-shadow:0 12px 35px #35439b55}
 #nesne-ui .star{position:absolute;left:760px;top:320px;font-size:240px;color:#ffc400;text-shadow:0 8px 0 #e99a00;animation:nesne-star .7s infinite alternate;z-index:110}
 @keyframes nesne-star{from{transform:scale(.8) rotate(-12deg)}to{transform:scale(1.15) rotate(12deg)}}
 `;document.head.append(css);
 let page='',level=0,cfg=null,locked=false,tiles=[],slots=[],selected=null,items=[],drag=null,timer=null,epoch=0,sound=true,music=null,score=new Set(),checked=false,star=null,starStart=0;
 let selectionTick=null;
 const all=n=>runtime.objects[n]?.getAllInstances()||[];
 function removeSelectionTick(){if(selectionTick){selectionTick.isVisible=false;selectionTick=null;}}
 function fit(){const canvas=document.querySelector('canvas');const r=canvas?.getBoundingClientRect();const w=r?.width||innerWidth,h=r?.height||innerHeight,s=Math.min(w/1920,h/1080);root.style.left=((r?.left||0)+(w-1920*s)/2)+'px';root.style.top=((r?.top||0)+(h-1080*s)/2)+'px';root.style.transform=`scale(${s})`;}
 addEventListener('resize',fit);
 function box(el,x,y,w,h){Object.assign(el.style,{position:'absolute',left:x-w/2+'px',top:y-h/2+'px',width:w+'px',height:h+'px'});return el;}
 function text(t,x,y,w,h,size=30){const e=document.createElement('div');e.textContent=t;box(e,x,y,w,h);e.style.cssText+=';display:flex;align-items:center;justify-content:center;text-align:center;font-size:'+size+'px';root.append(e);return e;}
 function btn(t,x,y,w,h,fn,hit=false){const e=document.createElement('button');e.textContent=t;box(e,x,y,w,h);if(hit)e.className='hit';e.onclick=()=>{unlock();fn();};root.append(e);return e;}
 function ownButton(name,label,fn,fallback){const i=all(name)[0];const g=i?[i.x,i.y,i.width,i.height]:fallback;if(!g)return null;const b=btn('',...g,fn,true);b.setAttribute('aria-label',label);if(!i){const img=document.createElement('img');img.src=ASSETS[name.toLowerCase()];img.style.cssText='width:100%;height:100%;object-fit:contain;pointer-events:none';b.append(img);}return b;}
 function say(t){if(!window.speechSynthesis)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='tr-TR';u.rate=.88;const v=speechSynthesis.getVoices().find(v=>v.lang.startsWith('tr'));if(v)u.voice=v;speechSynthesis.speak(u);}
 function unlock(){if(sound){if(!music){music=new Audio(ASSETS['fon']);music.loop=true;music.volume=.12;}music.play().catch(()=>{});}}
 function effect(ok){new Audio(ASSETS[ok?'dogrucevap':'yanliscevap']).play().catch(()=>{});}
 function go(name){removeSelectionTick();removeStar();clearTimeout(timer);epoch++;window.speechSynthesis?.cancel();runtime.goToLayout(name);}
 function boxType(){return level<=2?'Kutu':level===5?'kutu2':level===8?'kutu10':'kutu9';}
 function answerBoxes(){return all(boxType()).slice().sort((a,b)=>level===5?a.y-b.y:a.x-b.x);}
 function setFrame(inst,wrong){if(inst)inst.animationFrame=wrong?1:0;}
 function clearMarks(){for(const name of ['Kutu','kutu2','kutu3','kutu9','kutu10'])for(const inst of all(name))setFrame(inst,false);}
 function notice(){} // No written feedback.
 function removeStar(){root.querySelector('[data-celebration]')?.remove();if(star){star.destroy();star=null;}}
 function showStar(){removeStar();const type=runtime.objects.yildiz;if(!type)return;star=type.createInstance(0,960,500);star.isVisible=false;const image=document.createElement('img');image.src=ASSETS.yildiz;image.dataset.celebration='true';image.alt='';image.style.cssText='position:absolute;pointer-events:none;z-index:10000;object-fit:contain';box(image,960,500,1,678/1049);root.append(image);star.width=1;star.height=678/1049;starStart=performance.now();star.moveToTop?.();}
 function finish(ok){locked=true;checked=true;effect(ok);if(ok){score.add(level);showStar();}else score.delete(level);const gen=epoch;timer=setTimeout(()=>{if(epoch!==gen)return;if(level<10)go((level+1)+'.oyun');else ending();},1600);}
 function check(){if(locked)return;clearMarks();if(cfg.kind==='collect'){const ok=items.length===cfg.answer[0];if(!ok){const source=all(cfg.source).find(i=>i.y>750);if(source)source.colorRgb=[1,.25,.25];}finish(ok);return;}
 if(cfg.kind==='choose'){if(selected===null)return;const boxes=all('kutu3').slice().sort((a,b)=>a.x-b.x);setFrame(boxes[selected],selected!==cfg.answer[0]);finish(selected===cfg.answer[0]);return;}
 if(slots.some(s=>s.tile===null))return;
 let ok=true;slots.forEach((s,i)=>{const yes=tiles[s.tile].value===cfg.answer[i];ok=ok&&yes;setFrame(s.inst,!yes);});finish(ok);}
 function chooseX(i){return (level===6?[460,1007,1498]:[350,959,1582])[i];}
 function select(i){if(locked)return;clearMarks();selected=i;const boxes=all('kutu3').slice().sort((a,b)=>a.x-b.x);boxes.forEach(b=>b.opacity=1);removeSelectionTick();const target=boxes[i],type=runtime.objects.yesil_tik;if(!target||!type)return;selectionTick=all('yesil_tik')[0]||type.createInstance(target.layer?.index??0,target.x,target.y);selectionTick.x=target.x;selectionTick.y=target.y;selectionTick.z=target.z||0;selectionTick.opacity=1;const ratio=Math.abs(selectionTick.height/selectionTick.width)||1;selectionTick.width=Math.min(190,Math.abs(target.width)*.9);selectionTick.height=selectionTick.width*ratio;selectionTick.isVisible=true;selectionTick.moveToTop();}
 function tileElement(value,x,y,w,h,asset,word=false){const e=document.createElement('button');e.className='tile'+(word?' word':'');e.setAttribute('aria-label',String(value));if(asset){const img=document.createElement('img');img.src=ASSETS[asset];img.draggable=false;e.append(img);}else e.textContent=String(value);box(e,x,y,w,h);root.append(e);return e;}
 function positionTile(t,x,y){t.x=x;t.y=y;if(t.inst){t.inst.x=x;t.inst.y=y;t.inst.moveToTop();}box(t.el,x,y,t.w,t.h);}
 function place(t,s){if(s.tile!==null&&s.tile!==t.id){const prev=tiles[s.tile];prev.slot=null;positionTile(prev,prev.home[0],prev.home[1]);}if(t.slot!==null)slots[t.slot].tile=null;t.slot=s.id;s.tile=t.id;positionTile(t,s.x,s.y);selected=null;t.el.style.outline='';}
 function bindDrag(t,source=false){t.el.onpointerdown=e=>{if(locked||e.button>0)return;unlock();e.preventDefault();clearMarks();const p=point(e);drag={t,source,start:p,from:[t.x,t.y],moved:false,pointer:e.pointerId};if(source){drag.ghost=tileElement(cfg.source,t.x,t.y,t.w,t.h,cfg.source);drag.ghost.style.pointerEvents='none';drag.ghost.style.visibility='hidden';drag.ghost.style.zIndex='90';}t.el.setPointerCapture(e.pointerId);t.el.style.zIndex='60';};
 t.el.onpointermove=e=>{if(!drag||drag.t!==t||e.pointerId!==drag.pointer)return;const p=point(e);if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>10)drag.moved=true;if(drag.moved){const x=drag.from[0]+p.x-drag.start.x,y=drag.from[1]+p.y-drag.start.y;if(source){drag.ghost.style.visibility='visible';box(drag.ghost,x,y,t.w,t.h);}else positionTile(t,x,y);}};
 t.el.onpointerup=e=>{if(!drag||drag.t!==t)return;const d=drag;drag=null;t.el.style.zIndex='';if(source){d.ghost?.remove();const [x,y,w,h]=cfg.area;const p=point(e);if(d.moved&&p.x>x&&p.x<x+w&&p.y>y&&p.y<y+h)addItem(p.x,p.y);positionTile(t,...t.home);return;}
 if(!d.moved){selected=t.id;return;}
 const s=slots.find(s=>Math.abs(t.x-s.x)<s.w*.65&&Math.abs(t.y-s.y)<s.h*.7);if(s)place(t,s);else{if(t.slot!==null)slots[t.slot].tile=null;t.slot=null;positionTile(t,...t.home);}};
 t.el.onpointercancel=()=>{if(drag?.t===t){drag.ghost?.remove();positionTile(t,...drag.from);drag=null;}};
 t.el.onkeydown=e=>{if(locked)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=t.id;}if(e.key==='Escape'){selected=null;t.el.style.outline='';}};
 }
 function point(e){const r=root.getBoundingClientRect();return{x:(e.clientX-r.left)*1920/r.width,y:(e.clientY-r.top)*1080/r.height};}
 function inArea(p){const [x,y,w,h]=cfg.area;return p.x>=x&&p.x<=x+w&&p.y>=y&&p.y<=y+h;}
 function arrangeFlowers(){if(cfg.source==='top'){const base=items.filter(i=>i.initial),extra=items.filter(i=>!i.initial),[x,y,w,h]=cfg.area;const bottom=base.length?Math.max(...base.map(i=>i.y+i.h/2))+8:y;const rows=Math.max(1,Math.ceil(extra.length/10)),stepY=Math.min(100,(y+h-bottom)/rows),fh=Math.max(12,Math.min(74,stepY*.85)),fw=fh*169/133;const first=base.slice().sort((a,b)=>a.y-b.y||a.x-b.x).slice(0,10).sort((a,b)=>a.x-b.x);extra.forEach((item,i)=>{item.x=first[i%10]?.x??(x+(i%10+.5)*w/10);item.y=bottom+stepY*(Math.floor(i/10)+.5);item.w=fw;item.h=fh;box(item.el,item.x,item.y,fw,fh);});return;}const [x,y,w,h]=cfg.area,rows=Math.max(1,Math.ceil(items.length/10)),stepY=Math.min(110,(h-20)/rows),fw=Math.min(100,w/10-12,stepY*.9),fh=Math.min(110,stepY-5);items.forEach((item,i)=>{item.x=x+(i%10+.5)*w/10;item.y=y+12+stepY*(Math.floor(i/10)+.5);item.w=fw;item.h=fh;box(item.el,item.x,item.y,fw,fh);});}
 function addItem(x,y,initial=false){const e=tileElement(cfg.source==='top'?'Top':'Çiçek',x,y,65,65,cfg.source);const item={el:e,initial};items.push(item);
 if(!initial){if(cfg.source==='cicek')e.dataset.flower='true';else e.dataset.ball='true';e.setAttribute('aria-label',(cfg.source==='cicek'?'Çiçek':'Top')+': alan dışına sürükleyerek kaldır');let moving=null;
 e.onpointerdown=ev=>{if(locked||ev.button>0)return;ev.preventDefault();unlock();moving={pointer:ev.pointerId,start:point(ev),x:item.x,y:item.y,moved:false};e.setPointerCapture(ev.pointerId);e.style.zIndex='80';};
 e.onpointermove=ev=>{if(!moving||ev.pointerId!==moving.pointer)return;const p=point(ev);if(Math.hypot(p.x-moving.start.x,p.y-moving.start.y)>8)moving.moved=true;if(moving.moved)box(e,moving.x+p.x-moving.start.x,moving.y+p.y-moving.start.y,item.w,item.h);};
 e.onpointerup=ev=>{if(!moving||ev.pointerId!==moving.pointer)return;const remove=moving.moved&&!inArea(point(ev));moving=null;e.style.zIndex='';if(remove){items.splice(items.indexOf(item),1);e.remove();}arrangeFlowers();};
 e.onpointercancel=()=>{moving=null;e.style.zIndex='';arrangeFlowers();};arrangeFlowers();return;}
 e.onclick=()=>{if(locked||initial)return;items.splice(items.indexOf(item),1);e.remove();clearMarks();};e.setAttribute('aria-label',initial?'Başlangıç topu':'Eklenen nesneyi kaldır');if(initial)e.style.cursor='default';}
 function reset(){clearTimeout(timer);epoch++;start();}
 function menu(){const cover=document.createElement('div');cover.className='panel';box(cover,960,565,1360,710);root.append(cover);const h=document.createElement('h2');h.textContent='Etkinlik seç';h.style.textAlign='center';cover.append(h);for(let i=1;i<=10;i++){const b=document.createElement('button');b.textContent=(score.has(i)?'✓ ':'')+i+'. Etkinlik';b.style.margin='20px';b.onclick=()=>{unlock();go(i+'.oyun');};cover.append(b);}const b=document.createElement('button');b.textContent='Kapat';b.onclick=()=>cover.remove();cover.append(b);}
 function ending(){go('final');}
 function start(){removeSelectionTick();removeStar();clearTimeout(timer);epoch++;page=runtime.layout.name;level=Number(/^(\d+)\.oyun$/.exec(page)?.[1]||0);cfg=LEVELS[level];locked=false;checked=false,star=null,starStart=0;tiles=[];slots=[];items=[];selected=null;drag=null;root.replaceChildren();
 for(const [n,obj]of Object.entries(runtime.objects)){for(const i of obj.getAllInstances())i.isVisible=n.startsWith('Syf_')||n.startsWith('Btn_')||['Kutu','kutu2','kutu3','kutu9','kutu10'].includes(n);}
 clearMarks();fit();
 if(page==='final'){for(const inst of all('sonSayfa')){inst.isVisible=true;inst.animationSpeed=0;inst.animationFrame=score.size>=8?0:1;}return;}
 if(page==='ana_sayfa'){ownButton('Btn_basla','Başla',()=>{score.clear();go('1.oyun');});ownButton('Btn_bilgi','Bilgi',()=>go('bilgi'));ownButton('Btn_Nasil','Nasıl oynanır?',()=>go('nasil_oynanir'));return;}
 ownButton('Btn_ana','Ana sayfa',()=>go('ana_sayfa'));
 const mute=ownButton('Btn_ses_Ackapa',sound?'Fon müziğini kapat':'Fon müziğini aç',()=>{sound=!sound;mute.setAttribute('aria-label',sound?'Fon müziğini kapat':'Fon müziğini aç');for(const i of all('Btn_ses_Ackapa'))i.animationFrame=sound?0:1;if(sound)unlock();else music?.pause();});
 for(const i of all('Btn_ses_Ackapa'))i.animationFrame=sound?0:1;
 if(page==='nasil_oynanir'){text('Nesneleri say. Sayıyı ya da sayının yazılışını uygun kutuya sürükle.\nİstersen önce cevaba, sonra kutuya tıkla.\nÇiçek ve topları kaynaktan alana sürükle. Fazla eklediğini alan dışına sürükleyerek kaldır.\nBlok sorularında doğru grubun altındaki kutuyu seç.\n“Kontrol Et” ile cevabını kontrol et. Cevabın ardından sonraki soruya geçilir.',960,560,1430,540,39).style.whiteSpace='pre-line';return;}
 if(!cfg)return;
 text(level+' / 10',960,77,240,60,32).style.fontWeight='800';ownButton('Btn_kontrol','Kontrol Et',check);
 if(cfg.kind==='match'){cfg.slots.forEach((fallback,id)=>{const inst=answerBoxes()[id];const [x,y,w,h]=inst?[inst.x,inst.y,inst.width,inst.height]:fallback;const el=document.createElement('button');el.className='slot';box(el,x,y,w,h);el.setAttribute('aria-label',(id+1)+'. cevap kutusu');root.append(el);const s={id,x,y,w,h,el,inst,tile:null};slots.push(s);el.onclick=()=>{if(!locked&&selected!==null)place(tiles[selected],s);};});
 cfg.tiles.forEach((value,id)=>{
 if(cfg.words){const name=value===99?'S_99':'say'+value,inst=all(name)[0];if(!inst)return;inst.isVisible=true;inst.moveToTop();const {x,y,width:w,height:h}=inst;const el=tileElement(WORDS[value],x,y,w,h,null);el.textContent='';el.classList.add('hit');el.setAttribute('aria-label',WORDS[value]);const t={id,value,el,inst,x,y,w,h,home:[x,y],slot:null};tiles.push(t);bindDrag(t);return;}
 const [x,y]=cfg.positions[id],w=level===5?150:170,h=155;const el=tileElement(value,x,y,w,h,'s_'+value);const t={id,value,el,x,y,w,h,home:[x,y],slot:null};tiles.push(t);bindDrag(t);});
 }else if(cfg.kind==='collect'){if(cfg.initial){const initial=all(cfg.source).filter(i=>i.y<750).sort((a,b)=>a.y-b.y||a.x-b.x);for(const inst of initial){inst.isVisible=true;items.push({initial:true,inst,x:inst.x,y:inst.y,w:inst.width,h:inst.height});}}
 const sourceInst=all(cfg.source).find(i=>i.y>750);const x=sourceInst?.x||945,y=sourceInst?.y||835,w=sourceInst?.width||135,h=sourceInst?.height||135;const el=tileElement(cfg.source,x,y,w,h,null),t={el,x,y,w,h,home:[x,y]};el.textContent='';el.setAttribute('aria-label',cfg.source==='cicek'?'Çiçek kaynağı':'Top kaynağı');bindDrag(t,true);
 }else{[0,1,2].forEach(i=>{const b=btn('',chooseX(i),860,210,205,()=>select(i),true);b.setAttribute('aria-label',(i+1)+'. grubu seç');});}
 }
 return {start,tick(){if(runtime.layout.name!==page)start();if(star){const t=Math.min(1,(performance.now()-starStart)/650),ease=1-Math.pow(1-t,3);star.width=1+649*ease;star.height=star.width*678/1049;const image=root.querySelector('[data-celebration]');if(image)box(image,960,500,star.width,star.height);}}};
}
runOnStartup(async runtime=>{
 const game=createCountingGame(runtime);
 runtime.addEventListener('beforeprojectstart',()=>game.start());
 runtime.addEventListener('afteranylayoutstart',()=>game.start());
 runtime.addEventListener('tick',()=>game.tick());
});
